-- STAFF-ROSTER-2 (2026-11-04, charter pillar reach): the UX auditor's fix request follows real readers. It now picks the worst page of the last 3 hours per product
-- (the auditor, dashboard 1.86.0, checks every product host plus the pages and papers people viewed most in 7 days), and a slow page (over 1.5 s after one re-fetch)
-- files a request even when its score is 85 or more. An auth-gated page (401 or 403 sign-in wall, for example travel.q08.org) is never filed. Same workflow, cron and caps as STAFF-ROSTER-1.
-- APPLY-BY: ci
-- DB: qnfo-audit
-- Rollback: re-apply migrations/2026-11-04-staff-roster.sql (its INSERT OR REPLACE restores the first ux-request step).

UPDATE fleet_tasks SET definition = '{"steps": [{"type": "sql", "name": "personas", "db": "AUDIT", "sql": "INSERT OR IGNORE INTO management_personas (persona_key, level, scope, charter, decision_authority, sla_min, path_a, status, updated_at) VALUES (''ux:auditor'',''function'',''ux'',''Look at every product site the way a person meets it (layout, accessibility, typography, speed, broken pages) and keep raising the lowest score.'',''requests one fix per product per day through the roadmap path when the latest score is under 85; capped at 2 in flight'',60,''fleet_tasks staff-roster'',''active'',datetime(''now'')),(''project-manager:fleet'',''project'',''projects'',''Keep every active project moving: relink orphaned issues, complete finished projects and raise idle ones every hour.'',''links unmapped open issues to their program project, marks projects complete after 30 quiet days (revert in the action row), files up to 2 PROJECT-IDLE-1 issues per hour (6 open at most)'',120,''fleet_tasks staff-roster'',''active'',datetime(''now''))"}, {"type": "sql", "name": "ux-request", "db": "AUDIT", "sql": "INSERT INTO cf_agent_requests (requester, kind, prompt, instance, priority) SELECT ''program-manager:'' || r.program_code, ''run'', ''You are the UI and UX reviewer of '' || r.product || '' ('' || c.host || ''), run in the QNFO fleet (repository QNFO/qnfo-workers). A deterministic check of the live page just scored the page '' || c.host || '' at '' || c.score || '' of 100 (status '' || c.status || '', '' || c.ms || '' ms, '' || c.bytes || '' bytes). Findings (k = rule, d = points lost, n = count): '' || c.findings || ''. The code is '' || r.worker || ''/worker.js. Plus it: keep what works and make the smallest change that fixes the most points lost, for the person using a phone or a screen reader. Never read or quote personal data. Reply in exactly this form, each on its own line:'' || char(10) || ''TITLE: <under 80 characters>'' || char(10) || ''WHY: <who notices it and the finding it clears, under 60 words>'' || char(10) || ''code-task: repo=qnfo-workers path='' || r.worker || ''/worker.js'' || char(10) || ''code-anchor: <verbatim text that occurs exactly once in that file, next to the edit>'' || char(10) || ''EDIT: <the exact change, under 100 words>'', ''roadmap-'' || r.program_code || ''-ux-'' || r.product || ''-'' || strftime(''%Y%m%d'',''now''), ''low'' FROM product_registry r JOIN site_ux_checks c ON c.id = (SELECT x.id FROM site_ux_checks x WHERE x.product = r.product AND x.ts >= strftime(''%Y-%m-%dT%H:%M:%SZ'',''now'',''-3 hours'') AND x.status BETWEEN 200 AND 399 ORDER BY x.score ASC, x.ms DESC LIMIT 1) WHERE r.state = ''active'' AND r.worker IS NOT NULL AND (c.score < 85 OR c.findings LIKE ''%\"slow\"%'') AND c.findings NOT LIKE ''%auth-gated%'' AND c.status BETWEEN 200 AND 399 AND c.ts >= strftime(''%Y-%m-%dT%H:%M:%SZ'',''now'',''-3 hours'') AND NOT EXISTS (SELECT 1 FROM json_each(''[\"qnfo-fleet-control\",\"qnfo-ops\",\"qnfo-deploy-guard\",\"qnfo-containers-pilot\",\"qnfo-autonomy-scorer\",\"qnfo-observability\",\"qnfo-code-orchestrator\",\"qnfo-code-agent\",\"personal-api\",\"personal-companion\"]'') d WHERE d.value = r.worker) AND NOT EXISTS (SELECT 1 FROM cf_agent_requests q WHERE q.instance = ''roadmap-'' || r.program_code || ''-ux-'' || r.product || ''-'' || strftime(''%Y%m%d'',''now'')) AND NOT EXISTS (SELECT 1 FROM roadmap_proposals p WHERE p.request_instance LIKE ''roadmap-%-ux-'' || r.product || ''-%'' AND p.status IN (''proposed'',''filed'',''building'')) AND (SELECT COUNT(*) FROM cf_agent_requests q WHERE q.instance LIKE ''roadmap-%-ux-%'' AND q.status IN (''queued'',''running'')) < 2 ORDER BY c.score LIMIT 1"}, {"type": "sql", "name": "ux-log", "db": "AUDIT", "sql": "INSERT INTO persona_actions (persona_key, kind, from_value, to_value, evidence) SELECT ''ux:auditor'',''ux-request'', q.instance, ''queued'', ''site check under 85, one agent request filed through the roadmap path'' FROM cf_agent_requests q WHERE q.instance LIKE ''roadmap-%-ux-%'' AND q.created_at >= strftime(''%Y-%m-%dT%H:%M:%SZ'',''now'',''-2 hours'') AND NOT EXISTS (SELECT 1 FROM persona_actions a WHERE a.persona_key = ''ux:auditor'' AND a.from_value = q.instance)"}, {"type": "sql", "name": "ux-brief", "db": "AUDIT", "sql": "INSERT OR REPLACE INTO persona_briefs (tick, persona_key, level, scope, verdict, decision, summary) SELECT strftime(''%Y-%m-%dT%H:00:00Z'',''now''), ''ux:auditor'',''function'',''ux'', CASE WHEN COUNT(*) = 0 THEN ''no-data'' WHEN MIN(score) < 70 THEN ''poor'' WHEN MIN(score) < 85 THEN ''watch'' ELSE ''good'' END, ''one fix request per product per day under 85'', COALESCE(''Latest site scores: '' || group_concat(product || '' '' || score || '' ('' || ms || '' ms)'', '', '') || ''.'', ''No site check yet.'') FROM (SELECT c.product, c.score, c.ms FROM site_ux_checks c WHERE c.id IN (SELECT MAX(id) FROM site_ux_checks GROUP BY product) ORDER BY c.score)"}, {"type": "sql", "name": "pm-brief", "db": "AUDIT", "sql": "INSERT OR REPLACE INTO persona_briefs (tick, persona_key, level, scope, verdict, decision, summary) SELECT strftime(''%Y-%m-%dT%H:00:00Z'',''now''), ''project-manager:fleet'',''project'',''projects'', CASE WHEN idle > 40 THEN ''idle-heavy'' ELSE ''ok'' END, ''relinks, completes and raises idle projects'', active || '' active projects, '' || idle || '' with no open issue, '' || stale || '' not updated in 14 days.'' FROM (SELECT COUNT(*) AS active, SUM(NOT EXISTS (SELECT 1 FROM issue_project_map m JOIN agent_issues a ON a.id = m.issue_id AND a.status = ''open'' WHERE m.project_code = p.project_code)) AS idle, SUM(p.updated_at < datetime(''now'',''-14 days'')) AS stale FROM projects p WHERE p.status = ''active'')"}, {"type": "sql", "name": "pm-relink", "db": "AUDIT", "sql": "INSERT OR IGNORE INTO issue_project_map (issue_id, project_code, program_code, kind, updated_at) SELECT a.id, ''W.'' || x.prog, x.prog, ''fix'', datetime(''now'') FROM agent_issues a JOIN (SELECT a2.id AS iid, COALESCE((SELECT substr(a3.title, 12, instr(substr(a3.title, 12), '' '') - 1) FROM agent_issues a3 WHERE a3.id = a2.id AND a3.title LIKE ''ROADMAP-1: QNFO.%''), ''QNFO.OPS'') AS prog FROM agent_issues a2 WHERE a2.status = ''open'') x ON x.iid = a.id WHERE a.status = ''open'' AND NOT EXISTS (SELECT 1 FROM issue_project_map m WHERE m.issue_id = a.id) AND EXISTS (SELECT 1 FROM projects p WHERE p.project_code = ''W.'' || x.prog)"}, {"type": "sql", "name": "pm-relink-log", "db": "AUDIT", "sql": "INSERT INTO persona_actions (persona_key, kind, issue_id, from_value, to_value, evidence) SELECT ''project-manager:fleet'',''relink-issue'', m.issue_id, ''unmapped'', m.project_code, ''open issue had no project; linked to its program work project'' FROM issue_project_map m WHERE m.updated_at >= datetime(''now'',''-2 hours'') AND m.kind = ''fix'' AND NOT EXISTS (SELECT 1 FROM persona_actions a WHERE a.persona_key = ''project-manager:fleet'' AND a.kind = ''relink-issue'' AND a.issue_id = m.issue_id)"}, {"type": "sql", "name": "pm-complete", "db": "AUDIT", "sql": "UPDATE projects SET status = ''completed'', completed_at = datetime(''now''), updated_at = datetime(''now'') WHERE status = ''active'' AND updated_at < datetime(''now'',''-30 days'') AND EXISTS (SELECT 1 FROM issue_project_map m WHERE m.project_code = projects.project_code) AND NOT EXISTS (SELECT 1 FROM issue_project_map m JOIN agent_issues a ON a.id = m.issue_id WHERE m.project_code = projects.project_code AND (a.status = ''open'' OR a.updated_at >= datetime(''now'',''-30 days'')))"}, {"type": "sql", "name": "pm-complete-log", "db": "AUDIT", "sql": "INSERT INTO persona_actions (persona_key, kind, from_value, to_value, evidence) SELECT ''project-manager:fleet'',''project-complete'', p.project_code, ''completed'', ''no open issue and no issue activity for 30 days; revert: UPDATE projects SET status = ''''active'''' WHERE project_code = '''''' || p.project_code || '''''''' FROM projects p WHERE p.status = ''completed'' AND p.completed_at >= datetime(''now'',''-2 hours'') AND NOT EXISTS (SELECT 1 FROM persona_actions a WHERE a.persona_key = ''project-manager:fleet'' AND a.kind = ''project-complete'' AND a.from_value = p.project_code)"}, {"type": "sql", "name": "pm-idle-issue", "db": "AUDIT", "sql": "INSERT INTO agent_issues (title, description, source, category, priority, status, created_at, updated_at) SELECT ''PROJECT-IDLE-1: '' || p.project_code || '' has had no open work for 14 days'', ''The project manager found '' || p.project_code || '' ('' || p.name || '') active with no open issue and no update since '' || p.updated_at || ''. Closing condition: the project has an open roadmap or issue item that moves it, or it is marked completed with the evidence that its goal is met (projects.status). Doer: program manager of '' || p.program_code || ''.'', ''project-manager:fleet'', ''portfolio'', ''low'', ''open'', datetime(''now''), datetime(''now'') FROM projects p WHERE p.status = ''active'' AND p.updated_at < datetime(''now'',''-14 days'') AND NOT EXISTS (SELECT 1 FROM issue_project_map m JOIN agent_issues a ON a.id = m.issue_id AND a.status = ''open'' WHERE m.project_code = p.project_code) AND NOT EXISTS (SELECT 1 FROM agent_issues i WHERE i.status = ''open'' AND i.title LIKE ''PROJECT-IDLE-1: '' || p.project_code || '' %'') AND (SELECT COUNT(*) FROM agent_issues i WHERE i.status = ''open'' AND i.title LIKE ''PROJECT-IDLE-1: %'') < 6 ORDER BY p.updated_at LIMIT 2"}, {"type": "sql", "name": "metrics", "db": "AUDIT", "sql": "UPDATE metric_registry SET last_value = (SELECT CAST(MIN(score) AS TEXT) FROM site_ux_checks WHERE id IN (SELECT MAX(id) FROM site_ux_checks GROUP BY product)), last_refreshed = strftime(''%Y-%m-%dT%H:%M:%SZ'',''now''), state = ''MEASURED'' WHERE metric = ''site_ux_score_min'' AND EXISTS (SELECT 1 FROM site_ux_checks)"}, {"type": "sql", "name": "metrics2", "db": "AUDIT", "sql": "UPDATE metric_registry SET last_value = CAST((SELECT COUNT(DISTINCT persona_key) FROM persona_actions WHERE ts >= strftime(''%Y-%m-%dT%H:%M:%SZ'',''now'',''-24 hours'')) AS TEXT), last_refreshed = strftime(''%Y-%m-%dT%H:%M:%SZ'',''now''), state = ''MEASURED'' WHERE metric = ''staff_roles_acting_24h''"}]}', version = version + 1, updated_at = strftime('%Y-%m-%dT%H:%M:%SZ','now') WHERE id = 'staff-roster';
